193	func (s *APIV1Service) GetUserStats(ctx context.Context, request *v1pb.GetUserStatsRequest) (*v1pb.UserStats, error) {
194		user, err := ResolveUserByName(ctx, s.Store, request.Name)
195		if err != nil {
196			return nil, status.Errorf(codes.InvalidArgument, "invalid user name: %v", err)
197		}
198		if user == nil {
199			return nil, status.Errorf(codes.NotFound, "user not found")
200		}
201		userID := user.ID
202	
203		currentUser, err := s.fetchCurrentUser(ctx)
204		if err != nil {
205			return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
206		}
207	
208		normalStatus := store.Normal
209		memoFind := &store.FindMemo{
210			CreatorID: &userID,
211			// Exclude comments by default.
212			ExcludeComments: true,
213			ExcludeContent:  true,
214			RowStatus:       &normalStatus,
215		}
216	
217		if currentUser == nil {
218			memoFind.VisibilityList = []store.Visibility{store.Public}
219		} else if currentUser.ID != userID {
220			memoFind.VisibilityList = []store.Visibility{store.Public, store.Protected}
221		}
222	
223		createdTimestamps := []*timestamppb.Timestamp{}
224		updatedTimestamps := []*timestamppb.Timestamp{}
225		tagCount := make(map[string]int32)
226		linkCount := int32(0)
227		codeCount := int32(0)
228		todoCount := int32(0)
229		undoCount := int32(0)
230		pinnedMemos := []string{}
231		totalMemoCount := int32(0)
232	
233		limit := 1000
234		offset := 0
235		memoFind.Limit = &limit
236		memoFind.Offset = &offset
237	
238		for {
239			memos, err := s.Store.ListMemos(ctx, memoFind)
240			if err != nil {
241				return nil, status.Errorf(codes.Internal, "failed to list memos: %v", err)
242			}
243			if len(memos) == 0 {
244				break
245			}
246	
247			totalMemoCount += int32(len(memos))
248	
249			for _, memo := range memos {
250				createdTimestamps = append(createdTimestamps, timestamppb.New(time.Unix(memo.CreatedTs, 0)))
251				updatedTimestamps = append(updatedTimestamps, timestamppb.New(time.Unix(memo.UpdatedTs, 0)))
252				// Count different memo types based on content.
253				if memo.Payload != nil {
254					for _, tag := range memo.Payload.Tags {
255						tagCount[tag]++
256					}
257					if memo.Payload.Property != nil {
258						if memo.Payload.Property.HasLink {
259							linkCount++
260						}
261						if memo.Payload.Property.HasCode {
262							codeCount++
263						}
264						if memo.Payload.Property.HasTaskList {
265							todoCount++
266						}
267						if memo.Payload.Property.HasIncompleteTasks {
268							undoCount++
269						}
270					}
271				}
272				if memo.Pinned {
273					pinnedMemos = append(pinnedMemos, fmt.Sprintf("%s/memos/%d", BuildUserName(user.Username), memo.ID))
274				}
275			}
276	
277			offset += limit
278		}
279	
280		userStats := &v1pb.UserStats{
281			Name:                  fmt.Sprintf("%s/stats", BuildUserName(user.Username)),
282			MemoCreatedTimestamps: createdTimestamps,
283			MemoUpdatedTimestamps: updatedTimestamps,
284			TagCount:              tagCount,
285			PinnedMemos:           pinnedMemos,
286			TotalMemoCount:        totalMemoCount,
287			MemoTypeStats: &v1pb.UserStats_MemoTypeStats{
288				LinkCount: linkCount,
289				CodeCount: codeCount,
290				TodoCount: todoCount,
291				UndoCount: undoCount,
292			},
293		}
294	
295		return userStats, nil
296	}
